<?php
namespace qqworld_collector\module\collecting\method; use qqworld_collector\lib; use QL\QueryList; use voku\helper\HtmlDomParser; class selector extends lib { var $guid = 'selector'; var $ql = null; public function __construct() { add_filter( 'qqworld-collector-collecting-method-' . $this->guid, array($this, 'parse'), 10, 5); } public function inlucdes() { if ( $this->options->qc_collection_project_core == 'querylist' ) { if (!class_exists('QL\QueryList')) require WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR . 'querylist' . DIRECTORY_SEPARATOR . 'autoload.php'; if (!$this->ql) $this->ql = QueryList::getInstance(); } else { if (!function_exists('voku\helper\HtmlDomParser')) { require WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR . 'voku' . DIRECTORY_SEPARATOR . 'simple_html_dom' . DIRECTORY_SEPARATOR . 'autoload.php'; } } } public function __destruct() { if ($this->ql) $this->ql->destruct(); } public function get_result_from_element($element, $selector_method, $selector_attribute_name) { switch ($selector_method) { case 'innerHTML': if ( $this->options->qc_collection_project_core == 'querylist' ) { $result = $element->html(); } else { $result = $element->innertext(); $result = str_replace('&#13;', "\n", $result); } break; case 'outerHTML': if ( $this->options->qc_collection_project_core == 'querylist' ) { $result = $element->wrap('<div></div>')->parent()->html(); } else { $result = $element->outertext(); $result = str_replace('&#13;', "\n", $result); } break; case 'attribute': $attribute_names = explode('|', $selector_attribute_name); if (!empty($attribute_names)) foreach ($attribute_names as $attribute_name) { if ( $this->options->qc_collection_project_core == 'querylist' ) { $result = $element->attr($attribute_name); } else { $result = $element->$attribute_name; $result = str_replace('&#13;', "\n", $result); } if ($result) break; } break; } if ( $this->options->qc_collection_project_core == 'querylist' ) { $result = str_replace('<meta http-equiv="Content-Type" content="text/html;charset=UTF-8">', '', $result); } return $result; } public function parse($html, $value, $selector_method = 'innerHTML', $selector_attribute_name = 'href', $index = 'all') { $this->inlucdes(); $this->results = array(); $html = preg_replace('/<meta[^>]*?charset=[^>]*?>/i', '', $html); if ( $this->options->qc_collection_project_core == 'querylist' ) { $parser = $this->ql->html($html); $value = explode("\r\n", $value); foreach ($value as $val) { $val = html_entity_decode($val); if ($index == 'all') { $this->selector_method = $selector_method; $this->selector_attribute_name = $selector_attribute_name; $parser->find($val)->map(function($element) { $result = $this->get_result_from_element($element, $this->selector_method, $this->selector_attribute_name); if (!empty($result)) $this->results[] = $result; }); } else { if ($index == -1) { $length = $parser->find($val)->length(); $_index = $length-1; } else $_index = $index; $element = $parser->find($val)->eq($_index); if ($element) { $result = $this->get_result_from_element($element, $selector_method, $selector_attribute_name); } if (!empty($result)) $this->results[] = $result; } } } else { $parser = HtmlDomParser::str_get_html($html); if (is_object($parser)) { $value = explode("\r\n", $value); foreach ($value as $val) { $val = html_entity_decode($val); if ($index == 'all') { foreach ($parser->find($val) as $element) { $result = $this->get_result_from_element($element, $selector_method, $selector_attribute_name); if ($result) $this->results[] = $result; } } else { $element = $parser->find($val, $index); if ($element) { $result = $this->get_result_from_element($element, $selector_method, $selector_attribute_name); } if ($result) $this->results[] = $result; } } } if ($index != 'all' && count($this->results)>1) { if ($index == -1) $index = count($this->results)-1; $this->results = array_slice($this->results, $index, 1); } } return $this->results; } } ?>